    kept_rows = []
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            weight = int(row[1:-1])
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        keep = (state + weight + i) % 7 != 4 or i == len(rows) - 1
        if keep:
            kept_rows.append(row)

        if weight == 0:
            state = 5
        else:
            state = (5 * state + weight) % 7

    if not kept_rows:
        return []

